def md(d):
    sec=SECTIONS[next(code for code,x in D.items() if x is d)]
    s=f"# {d['title']}\n\n## {sec['meta']}\n- SEO Title: {d['title']}\n- Slug: {d['slug']}\n- Primary Keyword: {d['kw']}\n- Long-tail Keywords: {d['long']}\n- Meta Description: {d['meta']}\n- Tags: {d['tags']}\n- Language: {d['lang']}\n\n## {sec['update']}\n{d['intro']}\n\n"
    s+='\n'.join([f"- {x}" for x in d['points']])
    s+=f"\n\n## {sec['play']}\n{d['play']}\n\n## {sec['ug']}\n{d['ug']}\n\n## {sec['tips']}\n"+'\n'.join([f"{i+1}. {x}" for i,x in enumerate(d['steps'])])+f"\n\n## {sec['end']}\n{d['closing']}\n\n## {sec['source']}\n[{source}]({source})\n"
    return s

def docx(d,path):
    sec=SECTIONS[next(code for code,x in D.items() if x is d)]
    doc=Document(); page_sec=doc.sections[0]; page_sec.top_margin=Pt(48); page_sec.bottom_margin=Pt(48)
    st=doc.styles['Normal']; st.font.name='Arial'; st._element.rPr.rFonts.set(qn('w:eastAsia'),'Microsoft YaHei'); st.font.size=Pt(10.5)
    p=doc.add_paragraph(style='Title'); p.alignment=WD_ALIGN_PARAGRAPH.CENTER; p.add_run(d['title'])
    doc.add_heading(sec['meta'],1)
    for lab,key in [('SEO Title','title'),('Slug','slug'),('Primary Keyword','kw'),('Long-tail Keywords','long'),('Meta Description','meta'),('Tags','tags'),('Language','lang')]:
        p=doc.add_paragraph(); r=p.add_run(lab+': '); r.bold=True; p.add_run(d[key])
    doc.add_heading(sec['update'],1); doc.add_paragraph(d['intro'])
    for x in d['points']: doc.add_paragraph(x,style='List Bullet')
    doc.add_heading(sec['play'],1); doc.add_paragraph(d['play'])
    doc.add_heading(sec['ug'],1); doc.add_paragraph(d['ug'])
    doc.add_heading(sec['tips'],1)
    for x in d['steps']: doc.add_paragraph(x,style='List Number')
    doc.add_heading(sec['end'],1); doc.add_paragraph(d['closing'])
    doc.add_heading(sec['source'],1); doc.add_paragraph(source)
    doc.save(path)

for code,d in D.items():
    (out/f'anime-vanguards-2nd-anniversary-guide-{code}.md').write_text(md(d),encoding='utf-8')
    docx(d,out/f'anime-vanguards-2nd-anniversary-guide-{code}.docx')
